ine-offset:-3px}.glass-swatch{display:grid;width:52px;height:52px;place-items:center;border:1px solid #b8c9c3;border-radius:12px;background:#e7f1ef}.glass-swatch>span{width:24px;height:35px;border:2px solid #55827a;border-radius:2px;background:linear-gradient(120deg,#ffffffbb,#d7ece588)}.glass-swatch.verde{background:#e7f1e8}.glass-swatch.verde>span{border-color:#5c8260;background:linear-gradient(120deg,#c5dfc4,#81a98288)}.glass-swatch.fume{background:#eeefed}.glass-swatch.fume>span{border-color:#69716d;background:linear-gradient(120deg,#aeb5b1,#727b7788)}.glass-swatch.prata{background:#f2f3f3}.glass-swatch.prata>span{border-color:#909b97;background:linear-gradient(120deg,#fff,#bac6c288)}.product-main{display:grid;min-width:0;gap:4px}.product-main strong{font-size:17px}.product-main>span{color:#35423d;font:15px var(--font-verly-mono)}.product-main small{color:#63706b;font-size:15px}.product-price{display:grid;justify-items:end;gap:5px}.product-price small{color:#65716c;font-size:15px;text-align:right}.product-price strong{font:600 18px var(--font-verly-mono);white-space:nowrap}.product-chevron{color:#60706a}.price-example{display:grid;grid-template-columns:42px 1fr auto;align-items:center;gap:14px;margin-top:19px;padding:16px;border:1px solid #d6e2de;border-radius:14px;background:#f5f9f7}.example-icon{display:grid;width:42px;height:42px;place-items:center;border-radius:12px;background:#e2efeb;color:#246765}.price-example h2{margin:0 0 4px;font:600 18px var(--font-verly-display)}.price-example p{margin:0;color:#50605a;font-size:15px;line-height:1.45}.price-example p strong{color:#141a1f;font-family:var(--font-verly-mono)}.preview-dialog{width:min(720px,calc(100vw - 32px));max-width:none;max-height:90dvh;padding:0;border:0;border-radius:24px;background:#fff;color:#141a1f;box-shadow:0 22px 70px #101a1733;overflow:auto}.preview-dialog::backdrop{background:#121b19a6;backdrop-filter:blur(2px)}.dialog-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:18px;padding:23px 25px 18px;border-bottom:1px solid #e0e5e2}.dialog-heading h2{font-size:27px}.dialog-heading .preview-eyebrow{margin:0 0 7px}.dialog-close{display:grid;flex:none;width:44px;height:44px;place-items:center;border:1px solid #cbd5d0;border-radius:50%;background:#fff;color:#24302b;cursor:pointer}.product-detail-content{display:grid;gap:18px;padding:22px 25px}.detail-measures{display:flex;align-items:center;gap:14px;padding:15px;border-radius:12px;background:#f3f5f4}.glass-swatch.large{width:62px;height:62px}.glass-swatch.large>span{width:28px;height:43px}.detail-measures>div{display:grid;gap:4px}.detail-measures strong{font:600 18px var(--font-verly-mono)}.detail-measures span:not(.glass-swatch){color:#4d5b56;font-size:15px}.detail-measures small{color:#63706b;font-size:15px}.calculation-card{padding:16px;border:1px solid #dce2df;border-radius:12px}.calculation-card h3{margin:0 0 8px;font:600 19px var(--font-verly-display)}.calculation-card p{display:flex;justify-content:space-between;gap:14px;margin:0;padding:10px 0;border-bottom:1px solid #e6ebe8;color:#4a5852;font-size:15px}.calculation-card p strong{color:#1c2722;font:600 15px var(--font-verly-mono)}.calculation-card .calculation-margin{color:#52615b}.calculation-card .calculation-total{border-bottom:0;color:#141a1f;font-weight:700}.calculation-card .calculation-total strong{font-size:19px}.calculation-card>small{display:block;margin-top:9px;color:#68746f;font-size:15px;line-height:1.4}.dialog-actions{display:flex;justify-content:flex-end;gap:10px;padding:15px 25px 22px;border-top:1px solid #e0e5e2}.product-editor{width:min(650px,calc(100vw - 32px))}.editor-form{display:block}.product-fields{display:grid;gap:13px;padding:19px 25px}.editor-two{display:grid;grid-template-columns:1fr 1fr;gap:12px}.preview-form-field{display:grid;gap:6px;color:#34413c;font-size:15px;font-weight:600}.preview-form-field input,.preview-form-field select{width:100%;min-height:46px;padding:9px 11px;border:1px solid #9ea